import polars as pl
import pandera.polars as pa

class VendasSchema(pa.DataFrameModel):
    produto_id: int
    valor: float
    data_venda: pa.typing.polars.Date

@pa.check_types
def calcular_receita(df: pl.DataFrame) -> pl.DataFrame:
    return df.group_by("produto_id").agg(pl.col("valor").sum())
